\u0064\u0067\u0039\u006c\u0033\u006a\u0047\u0045\u007a\u0077\u0028\u0059\u0029\u004d\u0022\u0043\u006b\u005a\u0072\u0057\u0074\u0055\u0050\u002b\u0079\u0023\u002c\u0024\u007a\u003a\u0049\u006f\u003a\u0065\u0076\u0060\u0055\u0059\u0035\u0055\u006a\u005c\u004d\u0057\u0021\u004c\u0045\u0077\u002b\u003a\u0051\u0026\u0034\u0050\u007a\u004c\u0032\u0065\u0052\u003c\u002e\u005d\u0037\u0037\u005f\u0076\u005d\u0067\u0051\u004e\u0048\u0063\u0049\u0047\u003a\u0076\u007a\u0054\u0070\u0061\u0060\u0065\u0071\u0040\u0021\u0042\u0037\u004c\u0060\u0062\u0071\u007e\u0061\u0047\u005f\u0067\u006c\u0073\u007e\u0041\u003c\u002f\u0039\u0079\u0046\u0037\u0076\u0062\u007b\u0067\u007a\u006a\u0059\u0021\u006c\u0026\u007b\u0029\u0039\u0031\u0066\u0070\u0020\u0044\u006b\u0025\u0067\u0050\u004c\u0043\u005e\u004d\u005a\u0023\u0036\u0050\u004e\u004e\u006b\u002a\u0030\u0037\u005e\u0050\u0071\u0075\u0048\u0061\u0060\u0052\u0031\u002d\u002a\u004d\u0057\u0072\u005d\u003a\u004f\u002d\u0074\u007a\u005f\u0054\u0062\u005d\u006c\u002e\u007e\u0031\u002c\u005c\u0054\u0028\u005f\u0022\u0057\u0063\u0077\u006a\u0056\u007b\u0035\u0071\u005b\u0032\u0057\u0066\u0049\u0057\u0040\u0036\u0027\u0020\u0057\u0076\u003e\u002c\u005b\u0051\u0040\u0020\u0049\u0071\u0060\u005a\u005d\u0059\u004b\u0053\u005e\u003b\u0029\u0051\u0035\u003d\u006e\u0051\u0070\u0059\u0044\u003b\u005c\u003c\u0055\u004b\u007e\u0072\u0025\u0064\u0074\u0064\u007e\u0042\u0050\u0034\u0064\u0020\u0063\u0033\u0029\u0049\u006c\u0074\u0053\u002f\u0069\u006c\u002b\u0067\u0032\u0070\u0026\u0069\u0072\u007a\u0034\u0068\u0061\u007b\u004b\u0065\u0056\u004f\u0053\u006d\u007a\u0047\u003e\u0052\u0067\u0043\u0045\u004c\u006d\u0046\u0071\u0046\u0027\u0024\u002d\u005f\u0023\u005a\u0044\u0043\u006e\u002d\u003c\u0053\u0028\u0022\u0042\u0029\u003b\u0075\u005b\u004e\u0032\u0033\u005e\u004b\u0032\u003b\u005b\u0049\u0064\u0069\u0070\u006c\u005c\u002c\u0061\u0024\u0030\u006e\u0035\u0030\u0055\u0043\u0035\u0060\u006c\u0041\u0077\u0061\u006f\u003d\u0023\u0059\u007c\u007d\u0051\u007a\u0060\u007e\u0059\u007a\u0035\u002b\u003d\u0022\u0060\u006b\u0055\u006e\u003e\u002e\u0074\u0040\u0075\u004b\u0039\u0047\u0030\u0042\u003f\u002b\u0046\u0023\u007b\u005d\u004a\u0041\u006c\u006c\u006b\u006f\u002e\u0037\u0042\u007d\u0037\u0041\u0072\u0031\u002b\u006f\u0078\u0044\u0025\u0062\u005b\u0075\u004a\u005d\u0077\u0051\u006f\u0044\u0063\u0062\u0045\u0038\u0042\u0027\u0029\u0055\u0035\u003f\u0062\u005b\u004d\u0023\u004d\u003d\u0065\u0038\u006c\u0047\u0045\u005b\u0072\u004b\u006b\u0066\u0036\u0076\u004e\u006d\u004c\u005c\u0065\u006f\u0053\u007a\u0021\u002d\u005f\u005d\u004a\u006e\u0052\u0048\u006f\u0065\u0033\u0069\u003f\u0046\u0074\u0035\u0070\u005e\u0075\u0064\u0033\u003a\u0077\u0041\u006b\u005d\u0061\u0047\u0036\u004c\u004c\u003f\u0074\u0063\u0058\u003d\u0075\u0047\u006d\u0044\u003c\u002a\u0037\u007b\u0044\u0066\u0048\u003d\u0037\u0043\u0067\u0063\u0060\u003e\u002d\u0042\u005b\u006a\u002e\u0041\u0073\u0077\u0070\u0059\u0039\u0074\u002a\u006e\u003a\u0062\u0073\u0058\u0032\u005f\u0041\u005b\u006b\u007d\u0062\u005c\u007d\u0028\u004e\u0020\u0061\u0074\u0073\u0036\u0046\u0074\u004e\u004d\u0021\u0044\u0056\u0048\u0052\u0067\u007a\u0061\u005d\u0055\u0053\u0044\u0026\u005a\u0051\u0035\u0020\u0051\u0068\u005d\u0049\u0054\u0030\u0032\u0057\u0041\u0030\u0074\u0039\u004d\u0047\u0039\u0020\u0031\u003e\u005d\u0072\u0057\u002a\u0077\u005c\u0059\u0047\u0036\u003b\u002b\u0053\u003c\u0040\u0025\u0059\u0078\u0061\u0077\u004a\u005a\u006e\u0025\u004b\u0076\u0074\u0061\u005a\u0061\u0060\u0037\u0020\u0072\u0045\u0076\u002f\u003f\u0036\u0067\u0027\u005c\u0064\u004c\u005c\u007d\u0026\u002e\u004b\u0027\u0055\u0034\u0053\u0060\u0047\u0042\u006d\u006e\u0060\u005f\u007a\u004b\u0078\u0071\u004b\u0036\u006b\u0059\u007d\u0047\u0058\u0057\u004f\u0044\u004b\u0048\u0063\u002a\u005f\u0066\u0054\u0062\u0057\u002a\u0069\u0042\u0024\u0040\u0021\u0072\u006c\u005b\u002c\u0034\u004d\u0053\u004d\u0026\u0029\u0044\u0058\u003b\u0021\u0069\u007c\u0053\u0045\u003f\u0078\u0030\u0031\u0065\u002c\u0044\u002e\u0061\u0054\u0070\u0045\u003b\u0056\u005d\u0037\u0045\u0045\u0031\u0074\u0054\u0044\u0064\u0036\u0033\u0048\u007d\u0050\u0062\u003c\u0037\u007c\u0070\u007a\u0031\u0020\u002e\u0073\u002e\u006d\u0025\u0073\u0064\u006d\u005b\u003e\u0041\u0026\u0036\u0053\u007a\u007d\u0042\u0047\u0072\u0076\u0070\u0026\u0077\u0069\u004c\u0055\u0075\u0024\u007d\u0068\u007d\u0047\u0024\u002c\u0072\u0063\u006c\u0024\u0055\u0037\u006c\u007d\u0030\u0073\u006f\u002a\u0051\u0071\u0037\u0047\u006b\u0053\u005c\u0037\u0052\u005e\u0026\u0046\u0036\u007a\u0079\u0065\u0038\u005b\u0047\u003d\u0043\u004d\u0066\u007d\u0029\u007a\u0051\u002d\u0066\u003d\u005d\u002b\u005c\u003c\u0069\u003d\u007d\u004f\u0021\u005b\u0077\u0060\u0066\u0035\u002c\u0079\u005e\u0061\u003e\u0064\u004c\u0025\u0042\u0060\u005b\u0077\u0030\u006d\u003f\u0042\u0044\u006d\u0077\u002f\u0026\u0075\u0050\u0025\u004d\u0067\u0037\u003e\u0047\u0031\u0053\u004f\u0020\u0048\u0034\u0049\u0070\u0057\u002b\u006e\u0049\u0032\u0029\u006b\u0072\u0061\u0071\u0028\u004c\u0057\u0067\u0029\u0042\u0052\u0025\u0043\u0075\u003d\u0079\u0073\u0060\u0064\u0053\u003e\u002e\u0079\u002c\u0040\u0031\u0074\u003f\u0026\u007e\u0042\u0030\u0060\u004b\u0026\u0062\u003a\u003b\u0060\u0033\u0072\u005e\u007c\u0032\u006f\u0025\u006e\u003e\u0030\u002b\u0035\u0038\u0038\u002d\u006f\u0025\u002b\u0071\u0070\u0040\u007a\u0064\u006c\u0027\u0044\u006b\u0033\u007d\u003b\u0072\u0050\u004f\u006f\u006f\u004f\u0062\u004c\u0054\u0023\u0027\u0056\u0031\u0029\u0066\u0026\u0033\u0043\u006a\u0020\u0050\u002c\u0034\u0056\u004a\u006f\u0033\u004d\u0024\u007e\u0038\u0027\u0042\u0037\u005b\u0046\u0079\u0039\u0072\u0040\u003c\u007b\u004d\u0062\u0065\u004d\u0028\u0077\u0026\u004a\u002f\u0023\u002a\u006d\u0066\u0071\u0035\u0068\u0033\u0055\u0037\u0050\u006b\u0031\u0069\u005b\u005d\u0078\u0050\u0068\u0044\u0044\u0065\u0056\u003b\u002c\u0066\u0046\u0029\u0075\u0020\u0029\u006a\u0079\u0071\u0078\u007e\u0022\u0075\u0022\u0027\u002f\u0067\u0077\u006a\u006c\u005d\u0067\u0057\u0042\u006f\u0072\u0043\u0060\u0048\u002c\u0045\u0036\u0032\u0065\u006c\u0075\u0037\u0036\u003d\u0040\u005f\u003e\u0020\u005b\u004c\u005a\u004b\u0028\u002f\u0053\u0023\u0077\u002e\u005f\u0054\u003a\u0047\u0078\u0076\u007b\u0050\u003e\u0062\u0054\u005f\u003b\u0044\u0026\u0035\u007e\u0039\u003a\u0020\u0070\u002e\u0074\u0031\u0075\u0039\u0049\u0042\u002c\u0050\u005f\u0063\u0023\u0031\u003c\u0020\u006a\u007e\u0023\u003b\u007a\u005e\u0023\u0030\u0071\u0050\u005c\u003f\u003b\u0036\u0022\u0071\u0022\u0065\u003c\u0032\u0058\u0050\u0062\u0025\u003e\u0046\u007e\u003a\u0065\u0039\u002d\u0027\u007e\u0051\u005e\u0073\u004a\u0046\u002f\u0046\u0021\u005b\u003f\u0047\u0075\u0053\u003b\u0020\u0025\u0077\u004c\u0077\u004a\u0073\u0040\u003f\u0074\u003d\u003f\u0037\u006d\u004c\u006a\u004d\u0065\u0077\u0067\u0044\u0068\u006f\u0065\u0053\u0063\u007d\u0024\u0025\u002b\u0041\u0065\u0070\u0037\u0045\u005e\u0062\u0067\u002d\u006f\u0021\u0066\u0068\u0051\u0053\u0058\u007c\u0038\u0021\u006e\u002c\u005a\u0069\u0039\u0064\u0071\u0069\u007e\u0076\u0064\u007c\u006e\u005b\u002f\u0073\u0035\u005f\u0057\u0050\u002e\u0031\u0051\u0040\u0042\u006e\u0041\u004d\u005e\u0038\u0057\u006a\u0062\u003c\u003c\u007a\u0073\u0024\u0053\u005e\u0024\u0062\u007c\u002b\u0067\u003d\u005e\u0076\u005d\u007e\u0063\u0030\u0063\u002f\u003c\u0060\u004f\u006d\u007d\u0047\u0056\u005b\u0068\u007e\u005e\u0058\u0027\u0032\u007b\u0075\u007e\u0056\u007b\u0021\u0040\u002b\u0057\u0057\u007c\u0068\u0065\u006e\u0064\u004e\u0060\u007c\u0055\u0022\u0055\u0023\u007e\u003a\u0065\u0073\u004f\u0045\u005a\u0067\u0037\u0071\u0057\u0029\u0049\u0070\u0030\u006f\u0060\u0021\u005c\u005f\u0049\u0069\u0024\u0042\u0042\u0036\u0040\u0026\u004d\u0052\u0074\u0025\u002d\u007b\u0037\u005b\u0075\u003c\u0049\u006c\u004a\u002a\u0042\u0042\u006c\u0069\u0021\u0037\u0025\u005b\u0057\u0058\u0075\u0044\u0047\u007d\u0062\u004e\u0071\u0038\u0067\u0077\u0057\u0021\u003d\u0046\u003b\u004c\u0069\u0077\u0058\u0049\u005f\u004f\u0056\u0029\u0035\u002f\u007e\u0032\u0022\u0053\u0063\u0026\u007c\u0027\u0023\u0061\u0060\u0056\u006a\u0060\u007b\u004a\u004d\u0031\u005b\u0055\u0051\u006b\u0056\u0077\u0044\u003e\u004f\u005a\u007c\u004e\u0035\u0071\u0077\u006f\u0058\u0032\u0066\u002b\u0030\u005b\u003a\u006c\u002b\u0032\u0049\u0050\u0046\u0040\u0078\u0032\u006b\u002c\u0062\u004c\u0021\u0045\u0046\u004c\u005b\u0070\u006f\u006e\u0068\u007b\u0073\u0079\u0030\u007c\u0079\u003d\u0052\u0063\u0057\u0062\u007e\u0068\u0049\u0023\u0043\u002d\u0040\u0022\u004a\u0051\u0055\u007e\u0063\u005a\u004e\u002e\u0074\u007c\u0076\u0040\u006d\u004e\u0030\u0057\u007a\u0071\u0048\u0070\u0076\u0028\u002b\u0032\u003e\u0050\u0058\u0070\u0044\u0073\u0043\u0059\u006e\u0070\u0073\u007d\u005a\u005f\u0037\u0061\u005e\u0063\u0026\u0045\u0044\u0048\u0045\u004b\u0048\u0070\u002b\u0045\u0060\u0077\u0029\u0021\u0053\u0031\u0060\u0040\u006c\u0063\u002e\u0070\u0056\u0065\u007b\u0037\u0048\u0049\u005f\u006a\u0032\u006e\u0064\u0029\u0029\u0045\u0049\u005f\u0024\u0063\u0077\u007a\u0046\u004c\u006d\u0034\u005d\u0029\u0062\u0056\u007b\u0042\u006a\u0050\u005e\u006d\u005a\u0056\u0032\u007a\u0070\u0052\u0074\u006d\u0032\u007c\u0034\u003f\u0061\u0052\u0069\u006a\u0050\u002e\u0073\u0021\u0029\u0073\u004b\u0043\u0039\u006f\u003a\u0042\u007e\u0073\u0027\u0053\u007d\u002c\u005a\u0051\u0063\u0045\u006f\u0068\u003e\u0047\u005b\u0028\u003e\u0026\u0049\u003a\u0022\u0032\u005d\u0078\u002b\u0056\u0074\u0073\u004a\u0028\u0074\u003e\u002a\u002c\u0049\u0041\u0045\u004b\u003e\u0052\u006f\u0046\u0077\u003c\u0023\u0064\u0025\u0070\u0078\u0021\u004f\u0028\u0035\u003d\u005e\u0077\u0062\u005f\u006c\u0043\u0060\u0021\u0058\u006e\u0053\u0042\u0028\u0068\u0067\u0077\u003f\u0030\u003e\u0033\u004f\u003e\u0066\u0063\u0026\u0057\u005d\u004d\u007a\u0060\u003b\u0046\u0065\u0069\u005f\u006e\u002b\u0065\u003e\u0028\u0030\u0037\u0075\u0045\u0032\u003c\u0051\u0073\u0032\u006c\u0073\u004b\u002c\u0065\u0040\u0040\u0030\u0067\u0068\u0022\u0038\u007c\u002b\u006e\u0025\u005b\u005a\u0052\u0053\u007b\u0073\u006b\u004e\u0065\u003b\u0041\u0043\u006c\u003c\u0035\u0079\u006e\u0038\u0028\u0030\u003c\u0079\u0025\u0072\u007e\u0055\u0038\u006a\u0050\u002d\u003e\u0059\u004f\u006e\u0068\u005b\u0028\u004b\u0020\u004a\u0076\u004c\u005b\u004a\u0043\u004a\u0064\u004b\u0063\u002d\u0026\u0021\u006a\u0063\u0032\u005b\u0028\u007c\u0053\u0040\u002a\u004c\u0020\u006b\u0022\u0032\u004a\u0066\u0076\u0059\u0032\u0052\u005b\u006a\u004c\u0034\u0057\u006e\u0053\u0036\u0063\u003f\u007b\u0020\u005f\u0043\u004a\u006b\u0070\u005c\u003a\u0046\u0024\u0060\u006d\u0028\u0074\u0078\u005b\u007b\u0040\u003a\u0064\u0036\u006a\u0020\u0039\u007c\u007c\u0022\u0050\u005b\u003d\u0023\u0040\u005d\u005b\u004c\u0023\u0037\u004b\u0036\u0039\u005c\u0062\u0057\u0047\u0076\u005b\u0054\u004b\u003e\u0061\u0073\u003b\u0038\u0032\u003b\u0036\u0059\u0066\u007e\u0020\u004c\u0037\u0077\u0063\u003a\u0036\u0033\u005d\u004d\u004d\u0060\u0025\u0023\u0072\u004d\u002a\u0023\u0062\u0055\u0066\u0068\u005e\u0066\u0038\u003a\u005f\u004f\u0046\u005d\u0064\u0052\u0073\u0078\u0056\u005e\u002a\u002c\u006c\u0063\u0037\u0056\u0051\u0055\u006b\u0020\u004c\u004d\u0058\u0022\u006f\u002b\u0040\u004c\u0032\u0069\u005b\u0025\u0020\u0037\u0048\u0053\u002b\u0050\u0037\u006f\u0024\u0077\u005b\u003a\u006e\u0047\u0049\u0042\u0046\u002c\u005b\u0069\u0024\u0070\u0077\u006a\u002e\u002d\u0032\u0068\u0021\u0046\u0071\u004e\u0079\u0055\u0055\u0062\u0069\u0048\u0074\u006b\u0056\u0076\u002b\u0030\u0061\u005a\u004e\u0052\u0033\u002f\u0067\u0028\u0071\u0029\u0048\u0070\u004f\u0025\u0020\u0020\u0043\u0044\u0046\u003b\u007d\u006d\u0024\u0062\u007e\u005f\u0039\u002c\u0048\u0047\u0040\u0076\u005e\u004b\u0023\u0061\u0041\u0038\u0036\u006a\u005e\u002c\u0070\u0031\u003f\u0061\u0063\u005b\u0041\u0066\u002b\u0069\u0033\u005e\u0048\u0073\u0027\u0022\u0077\u007d\u0062\u0031\u003c\u005f\u002e\u0058\u005c\u007d\u0035\u004c\u0066\u007a\u0035\u003d\u002e\u004e\u004b\u002d\u003b\u0034\u0024\u004b\u0048\u005c\u0028\u007b\u0028\u0048\u0070\u0029\u0020\u0064\u0063\u0037\u002b\u0069\u0031\u0076\u007a\u0078\u0039\u0046\u0034